using System.Diagnostics;
using System.Text.Json;
using CardGame.Core;
using CardGame.Content.Standard;

var metrics = new List<object>();
object? sink = null;

void Measure(string name, int iterations, Func<object?> operation)
{
    for (var i = 0; i < 5; i++) sink = operation();
    var times = new List<double>();
    var bytes = new List<double>();
    for (var batch = 0; batch < 7; batch++)
    {
        var allocation = GC.GetAllocatedBytesForCurrentThread();
        var start = Stopwatch.GetTimestamp();
        for (var i = 0; i < iterations; i++) sink = operation();
        times.Add(Stopwatch.GetElapsedTime(start).TotalMilliseconds / iterations);
        bytes.Add((GC.GetAllocatedBytesForCurrentThread() - allocation) / (double)iterations);
    }
    var ordered = times.Order().ToArray();
    var result = new {
        name, iterationsPerBatch = iterations, batches = times.Count,
        medianMsPerOperation = ordered[ordered.Length / 2],
        minimumMsPerOperation = ordered[0], maximumMsPerOperation = ordered[^1],
        meanAllocatedBytesPerOperation = bytes.Average(),
        batchMsPerOperation = times
    };
    metrics.Add(result);
    Console.WriteLine(JsonSerializer.Serialize(result));
}

Measure("base catalog build", 20, () => StandardContentRegistry.Create());
Measure("expanded catalog build", 10, () => StandardContentRegistry.CreateWithClassicGenerals());
var baseRegistry = StandardContentRegistry.Create();
var expanded = StandardContentRegistry.CreateWithClassicGenerals();
var catalogSizes = new[] { ("base",baseRegistry), ("expanded",expanded) }.Select(x =>
    new { name=x.Item1, cards=x.Item2.Cards.Count, skills=x.Item2.Skills.Count, generals=x.Item2.Generals.Count, modes=x.Item2.Modes.Count, contentHash=x.Item2.ContentHash }).ToArray();

foreach (var entry in new[] {
    (name:"base standard mode", registry:baseRegistry, mode:"identity:standard-8"),
    (name:"expanded same standard mode", registry:expanded, mode:"identity:standard-8") })
{
    var options = new GameOptions { Seed=1, PlayerCount=8, HumanSeat=0, HumanRole=Role.Lord,
        ModeId=entry.mode, UseInteractiveSetup=false, AdvanceAfterHumanCommands=false };
    Measure(entry.name + " engine construction with reused catalog", 20,
        () => GameEngine.CreateStandard(options,entry.registry));
    var game = GameEngine.CreateStandard(options,entry.registry);
    var startResult = game.Submit(new StartGameCommand());
    if (!startResult.Accepted) throw new InvalidOperationException("Start was rejected for "+entry.name);
    // Single-step host policy keeps this bounded. Advance only to the first human decision.
    for (var i=0; i<100 && game.State.PendingDecision is null; i++)
        if (!game.Submit(new AdvanceOneStepCommand(game.Revision)).Accepted)
            throw new InvalidOperationException("Advance was rejected for "+entry.name);
    if (game.State.PendingDecision is not { Kind:DecisionKind.PlayCard, PlayerSeat:0 })
        throw new InvalidOperationException("Expected actual human PlayCard boundary for "+entry.name);
    Measure(entry.name + " player snapshot", 200, () => game.CreateSnapshot(0));
    Measure(entry.name + " legal actions", 100, () => game.GetHumanLegalActions());
    Measure(entry.name + " hand guidance", 100, () => game.GetHumanHandGuidance());
    Measure(entry.name + " combined action view", 100, () => game.GetHumanActionView());
    Measure(entry.name + " checkpoint capture", 100, () => game.CreateCheckpoint());
    var checkpoint = game.CreateCheckpoint();
    var checkpointJson = GameCheckpointJson.Serialize(checkpoint);
    Measure(entry.name + " checkpoint JSON roundtrip", 50,
        () => GameCheckpointJson.Deserialize(GameCheckpointJson.Serialize(checkpoint)));
    Measure(entry.name + " restore short accepted prefix", 20, () => GameReplay.Restore(checkpoint,entry.registry));
    metrics.Add(new {name=entry.name+" fixture",revision=game.Revision,
        commands=game.AcceptedCommands.Count,checkpointJsonBytes=System.Text.Encoding.UTF8.GetByteCount(checkpointJson),
        prompt=game.State.PendingDecision!.Kind.ToString(),seed=options.Seed,mode=entry.mode});
}
GC.KeepAlive(sink);
File.WriteAllText(args[0],JsonSerializer.Serialize(new {
    measuredAt=DateTimeOffset.Now,method="Seven warmed batches with tiered compilation disabled for stable optimized JIT, allocation measured on the executing managed thread. Fixed seed=1, 8 seats, same standard active general pool and human PlayCard boundary for both catalogs; short-prefix replay. Isolates catalog-size overhead, not classic-pool gameplay. This is a microbenchmark, not long-game/UI acceptance or a historical regression comparison.",
    catalogs=catalogSizes,metrics
},new JsonSerializerOptions {WriteIndented=true}));
